package com.choutuan.order;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.BeforeEach; import org.junit.jupiter.api.Test; import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter; import org.springframework.test.web.servlet.MockMvc; import org.springframework.test.web.servlet.MvcResult; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import java.math.BigDecimal;
import static org.hamcrest.Matchers.hasSize; import static org.junit.jupiter.api.Assertions.assertEquals; import static org.junit.jupiter.api.Assertions.assertTrue; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
class RevenueAnalyticsControllerTest { private MockMvc mockMvc; @BeforeEach void setUp() { mockMvc = MockMvcBuilders.standaloneSetup(new RevenueAnalyticsController()).setMessageConverters(new MappingJackson2HttpMessageConverter()).build(); } @Test void summaryShouldReturnZeroCommissionAndSevenDayBreakdown() throws Exception { MvcResult result = mockMvc.perform(get("/order-service/api/v1/analytics/summary").header("X-Tenant-Id", "tenant_food_1")).andExpect(status().isOk()).andExpect(jsonPath("$.tenantId").value("tenant_food_1")).andExpect(jsonPath("$.periodDays").value(7)).andExpect(jsonPath("$.dailyBreakdown", hasSize(7))).andReturn(); JsonNode root = new ObjectMapper().readTree(result.getResponse().getContentAsString()); assertEquals(0, root.get("platformCommissionRate").decimalValue().compareTo(BigDecimal.ZERO)); assertEquals(0, root.get("platformCommissionFee").decimalValue().compareTo(BigDecimal.ZERO)); assertTrue(root.get("savedCommissionTotal").decimalValue().compareTo(BigDecimal.ZERO) > 0); } }
